package cn.lili.modules.community.p0.channel;
import com.google.gson.JsonObject;
import java.util.Map;
/** Only non-funding ecommerce endpoints. Request identities are generated by the application service. */
public interface OnboardingChannelPort {
    void validateMaterials(JsonObject mapped);
    String uploadMaterial(String name,String mime,byte[] bytes);
    JsonObject submitApplication(String outRequestNo,JsonObject mapped);
    JsonObject queryByOutRequestNo(String outRequestNo);
    JsonObject queryByApplymentId(String applymentId);
    Map<String,Object> verifyRelation(JsonObject authoritativeApplication,String paymentAppId);
    JsonObject ensureReceiverRelation(JsonObject receiver);
}
